'use client';

import * as React from 'react';
import { Menu as BaseMenu } from '@base-ui/react/menu';
import { Icon } from './icon';
import { ScrollArea } from './scroll-area';
import { cn, composeClassName, resolveNativeButton, sanitizeUrl } from '@/lib/utils';

const MenuFilterScopeContext = React.createContext(false);

export interface MenuItemData {
  id: string;
  label: string;
  icon?: string;
  destructive?: boolean;
  disabled?: boolean;
  onClick?: () => void;
}

export interface MenuItemProps extends React.ComponentPropsWithoutRef<typeof BaseMenu.Item> {
  destructive?: boolean;
  icon?: string;
}

export const MenuItem = React.forwardRef<HTMLDivElement, MenuItemProps>(
  ({ className, destructive, icon, children, ...props }, ref) => (
    <BaseMenu.Item
      ref={ref}
      data-slot="menu-item"
      className={composeClassName(
        cn(
          'flex items-center gap-2.5 px-3 py-2 min-h-[44px] rounded-sm font-sans text-sm font-medium cursor-pointer outline-none transition-colors motion-reduce:transition-none select-none',
          destructive
            ? 'text-error hover:bg-error/10 focus:bg-error/10 data-[highlighted]:bg-error/10 data-[highlighted]:text-error'
            : 'text-on-surface hover:bg-state-hover focus:bg-state-hover data-[highlighted]:bg-state-hover data-[highlighted]:text-on-surface',
          'data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed data-[disabled]:pointer-events-none'
        ),
        className
      )}
      {...props}
    >
      {icon && <Icon name={icon} size="md" className="shrink-0" aria-hidden="true" />}
      <span className="truncate flex-1">{children}</span>
    </BaseMenu.Item>
  )
);
MenuItem.displayName = 'MenuItem';

export interface MenuArrowProps
  extends React.ComponentPropsWithoutRef<typeof BaseMenu.Arrow> {}

export const MenuArrow = React.forwardRef<HTMLDivElement, MenuArrowProps>(
  ({ className, children, ...props }, ref) => (
    <BaseMenu.Arrow
      ref={ref}
      data-slot="menu-arrow"
      className={composeClassName(
        cn(
          'z-10 data-[side=top]:bottom-[-5px] data-[side=bottom]:top-[-5px] data-[side=left]:right-[-7.5px] data-[side=right]:left-[-7.5px] data-[side=inline-start]:end-[-7.5px] data-[side=inline-end]:start-[-7.5px]',
          'data-[side=top]:rotate-180 data-[side=left]:rotate-90 data-[side=right]:-rotate-90 data-[side=inline-start]:rotate-90 rtl:data-[side=inline-start]:-rotate-90 data-[side=inline-end]:-rotate-90 rtl:data-[side=inline-end]:rotate-90'
        ),
        className
      )}
      {...props}
    >
      {children ?? (
        <svg
          width="10"
          height="5"
          viewBox="0 0 10 5"
          className="block fill-surface stroke-outline-variant"
          aria-hidden="true"
        >
          <path d="M0 5 L5 0 L10 5" />
        </svg>
      )}
    </BaseMenu.Arrow>
  )
);
MenuArrow.displayName = 'MenuArrow';

const basePositionerClasses =
  'z-50 max-w-[min(var(--available-width),calc(100vw-1rem))] outline-none transition-[top,left,right,bottom] duration-[var(--duration-fast)] ease-[var(--ease-standard)] data-[instant]:transition-none motion-reduce:transition-none';

const basePopupClasses =
  'relative flex flex-col min-w-[200px] max-w-[min(var(--available-width),calc(100vw-1rem))] max-h-[min(24rem,var(--available-height))] rounded bg-surface border border-outline-variant shadow-ambient outline-none transition-[opacity,transform,width,height] duration-[var(--duration-fast)] data-[ending-style]:duration-[var(--duration-quick)] origin-[var(--transform-origin)] data-[starting-style]:opacity-0 data-[starting-style]:scale-[var(--scale-medium)] data-[ending-style]:opacity-0 data-[ending-style]:scale-[var(--scale-medium)] ease-[var(--ease-standard)] motion-reduce:transition-none motion-reduce:transform-none data-[instant]:transition-none data-[instant]:transform-none';

export const MenuPositioner = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.Positioner>
>(({ className, sideOffset = 4, collisionPadding = 8, ...props }, ref) => (
  <BaseMenu.Positioner
    ref={ref}
    data-slot="menu-positioner"
    sideOffset={sideOffset}
    collisionPadding={collisionPadding}
    className={composeClassName(basePositionerClasses, className)}
    {...props}
  />
));
MenuPositioner.displayName = 'MenuPositioner';

export const MenuPopup = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.Popup>
>(({ className, ...props }, ref) => (
  <BaseMenu.Popup
    ref={ref}
    data-slot="menu-content"
    className={composeClassName(basePopupClasses, className)}
    {...props}
  />
));
MenuPopup.displayName = 'MenuPopup';

export const MenuViewport = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.Viewport>
>(({ className, ...props }, ref) => (
  <BaseMenu.Viewport
    ref={ref}
    data-slot="menu-viewport"
    className={composeClassName(
      'relative size-full overflow-hidden rounded-[inherit]',
      className
    )}
    {...props}
  />
));
MenuViewport.displayName = 'MenuViewport';

export interface MenuContentProps extends React.ComponentPropsWithoutRef<typeof BaseMenu.Popup> {
  side?: BaseMenu.Positioner.Props['side'];
  align?: BaseMenu.Positioner.Props['align'];
  sideOffset?: BaseMenu.Positioner.Props['sideOffset'];
  alignOffset?: BaseMenu.Positioner.Props['alignOffset'];
  anchor?: BaseMenu.Positioner.Props['anchor'];
  positionMethod?: BaseMenu.Positioner.Props['positionMethod'];
  sticky?: BaseMenu.Positioner.Props['sticky'];
  collisionPadding?: BaseMenu.Positioner.Props['collisionPadding'];
  collisionBoundary?: BaseMenu.Positioner.Props['collisionBoundary'];
  collisionAvoidance?: BaseMenu.Positioner.Props['collisionAvoidance'];
  arrowPadding?: BaseMenu.Positioner.Props['arrowPadding'];
  disableAnchorTracking?: BaseMenu.Positioner.Props['disableAnchorTracking'];
  container?: BaseMenu.Portal.Props['container'];
  containerClassName?: BaseMenu.Positioner.Props['className'];
  keepMounted?: boolean;
  showArrow?: boolean;
  scrollable?: boolean;
}

export const MenuContent = React.forwardRef<HTMLDivElement, MenuContentProps>(
  (
    {
      className,
      children,
      side,
      align,
      sideOffset = 4,
      alignOffset,
      anchor,
      positionMethod,
      sticky,
      collisionPadding = 8,
      collisionBoundary,
      collisionAvoidance,
      arrowPadding,
      disableAnchorTracking,
      container,
      containerClassName,
      keepMounted,
      showArrow = false,
      scrollable = true,
      ...props
    },
    ref
  ) => {
    const isFilterable = React.useContext(MenuFilterScopeContext);
    const childList = React.Children.toArray(children);
    const arrowChildren: React.ReactNode[] = [];
    const bodyChildren: React.ReactNode[] = [];

    for (const child of childList) {
      if (React.isValidElement(child) && (child.type === MenuArrow || child.type === BaseMenu.Arrow)) {
        arrowChildren.push(child);
      } else {
        bodyChildren.push(child);
      }
    }

    const useOuterScroll = scrollable && !isFilterable;

    return (
      <BaseMenu.Portal container={container} keepMounted={keepMounted}>
        <MenuPositioner
          side={side}
          align={align}
          sideOffset={sideOffset}
          alignOffset={alignOffset}
          anchor={anchor}
          positionMethod={positionMethod}
          sticky={sticky}
          collisionPadding={collisionPadding}
          collisionBoundary={collisionBoundary}
          collisionAvoidance={collisionAvoidance}
          arrowPadding={arrowPadding}
          disableAnchorTracking={disableAnchorTracking}
          className={containerClassName}
        >
          <MenuPopup ref={ref} className={className} {...props}>
            {arrowChildren.length > 0 ? arrowChildren : showArrow ? <MenuArrow /> : null}
            {useOuterScroll ? (
              <ScrollArea
                className="min-h-0 flex-[0_1_auto]"
                viewportClassName="overscroll-contain scroll-py-1"
                viewportProps={{
                  tabIndex: -1,
                  onMouseDown: (e) => {
                    const target = e.target as HTMLElement | null;
                    if (target?.closest('input, textarea, [contenteditable]')) return;
                    e.preventDefault();
                  },
                }}
                contentClassName="p-1"
              >
                {bodyChildren}
              </ScrollArea>
            ) : (
              bodyChildren
            )}
          </MenuPopup>
        </MenuPositioner>
      </BaseMenu.Portal>
    );
  }
);
MenuContent.displayName = 'MenuContent';

export const MenuSeparator = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.Separator>
>(({ className, ...props }, ref) => (
  <BaseMenu.Separator
    ref={ref}
    data-slot="menu-separator"
    className={composeClassName('h-px my-1 bg-outline-variant/60 -mx-1', className)}
    {...props}
  />
));
MenuSeparator.displayName = 'MenuSeparator';

export const MenuShortcut = React.forwardRef<
  HTMLSpanElement,
  React.HTMLAttributes<HTMLSpanElement>
>(({ className, ...props }, ref) => (
  <span
    ref={ref}
    data-slot="menu-shortcut"
    className={cn('font-mono text-xs text-on-surface-variant font-medium tracking-wider ms-auto', className)}
    {...props}
  />
));
MenuShortcut.displayName = 'MenuShortcut';

export interface MenuTriggerProps<Payload = unknown>
  extends BaseMenu.Trigger.Props<Payload> {
  size?: 'sm' | 'md' | 'lg';
}

const menuTriggerSizeClasses: Record<'sm' | 'md' | 'lg', string> = {
  sm: 'h-11 px-4 min-h-[44px] text-sm',
  md: 'h-12 px-4 min-h-[48px] text-sm',
  lg: 'h-14 px-5 min-h-[56px] text-base',
};

export const MenuTrigger = React.forwardRef(function MenuTrigger<Payload = unknown>(
  { className, children, size = 'sm', render, nativeButton, ...props }: MenuTriggerProps<Payload>,
  ref: React.ForwardedRef<HTMLButtonElement>
) {
  return (
    <BaseMenu.Trigger
      ref={ref}
      data-slot="menu-trigger"
      render={render}
      nativeButton={resolveNativeButton(render, nativeButton)}
      className={
        render
          ? className
          : composeClassName(
              cn(
                'inline-flex items-center justify-between gap-2 rounded border border-outline bg-surface text-on-surface font-label font-semibold hover:bg-state-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary transition-colors motion-reduce:transition-none cursor-pointer select-none disabled:opacity-50 disabled:cursor-not-allowed',
                menuTriggerSizeClasses[size]
              ),
              className
            )
      }
      {...props}
    >
      {children}
    </BaseMenu.Trigger>
  );
}) as (<Payload = unknown>(
  props: MenuTriggerProps<Payload> & React.RefAttributes<HTMLButtonElement>
) => React.JSX.Element) & { displayName?: string };
MenuTrigger.displayName = 'MenuTrigger';

export interface MenuCheckboxItemProps
  extends React.ComponentPropsWithoutRef<typeof BaseMenu.CheckboxItem> {
  icon?: string;
}

export const MenuCheckboxItem = React.forwardRef<HTMLDivElement, MenuCheckboxItemProps>(
  ({ className, children, icon, ...props }, ref) => (
    <BaseMenu.CheckboxItem
      ref={ref}
      data-slot="menu-checkbox-item"
      className={composeClassName(
        'flex items-center justify-between gap-2.5 px-3 py-2 min-h-[44px] rounded-sm font-sans text-sm font-medium cursor-pointer outline-none transition-colors motion-reduce:transition-none select-none text-on-surface hover:bg-state-hover focus:bg-state-hover data-[highlighted]:bg-state-hover data-[highlighted]:text-on-surface data-[checked]:font-semibold data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed data-[disabled]:pointer-events-none',
        className
      )}
      {...props}
    >
      <div className="flex flex-1 min-w-0 items-center gap-2.5 truncate">
        {icon && <Icon name={icon} size="md" className="shrink-0" aria-hidden="true" />}
        <span className="truncate flex-1">{children}</span>
      </div>
      <BaseMenu.CheckboxItemIndicator className="shrink-0 text-primary flex items-center justify-center">
        <Icon name="check" size="sm" aria-hidden="true" />
      </BaseMenu.CheckboxItemIndicator>
    </BaseMenu.CheckboxItem>
  )
);
MenuCheckboxItem.displayName = 'MenuCheckboxItem';

export interface MenuRadioItemProps
  extends React.ComponentPropsWithoutRef<typeof BaseMenu.RadioItem> {
  icon?: string;
}

export const MenuRadioItem = React.forwardRef<HTMLDivElement, MenuRadioItemProps>(
  ({ className, children, icon, ...props }, ref) => (
    <BaseMenu.RadioItem
      ref={ref}
      data-slot="menu-radio-item"
      className={composeClassName(
        'flex items-center justify-between gap-2.5 px-3 py-2 min-h-[44px] rounded-sm font-sans text-sm font-medium cursor-pointer outline-none transition-colors motion-reduce:transition-none select-none text-on-surface hover:bg-state-hover focus:bg-state-hover data-[highlighted]:bg-state-hover data-[highlighted]:text-on-surface data-[checked]:font-semibold data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed data-[disabled]:pointer-events-none',
        className
      )}
      {...props}
    >
      <div className="flex flex-1 min-w-0 items-center gap-2.5 truncate">
        {icon && <Icon name={icon} size="md" className="shrink-0" aria-hidden="true" />}
        <span className="truncate flex-1">{children}</span>
      </div>
      <BaseMenu.RadioItemIndicator className="shrink-0 text-primary flex items-center justify-center">
        <Icon name="radio_button_checked" size="sm" aria-hidden="true" />
      </BaseMenu.RadioItemIndicator>
    </BaseMenu.RadioItem>
  )
);
MenuRadioItem.displayName = 'MenuRadioItem';

export interface MenuSubmenuTriggerProps
  extends React.ComponentPropsWithoutRef<typeof BaseMenu.SubmenuTrigger> {
  icon?: string;
}

export const MenuSubmenuTrigger = React.forwardRef<HTMLDivElement, MenuSubmenuTriggerProps>(
  ({ className, children, icon, ...props }, ref) => (
    <BaseMenu.SubmenuTrigger
      ref={ref}
      data-slot="menu-sub-trigger"
      className={composeClassName(
        'flex items-center justify-between gap-2.5 px-3 py-2 min-h-[44px] rounded-sm font-sans text-sm font-medium cursor-pointer outline-none transition-colors motion-reduce:transition-none select-none text-on-surface hover:bg-state-hover focus:bg-state-hover data-[highlighted]:bg-state-hover data-[highlighted]:text-on-surface data-[popup-open]:bg-state-hover data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed data-[disabled]:pointer-events-none',
        className
      )}
      {...props}
    >
      <div className="flex flex-1 min-w-0 items-center gap-2.5 truncate">
        {icon && <Icon name={icon} size="md" className="shrink-0" aria-hidden="true" />}
        <span className="truncate flex-1">{children}</span>
      </div>
      <Icon name="chevron_right" size="sm" directional className="text-on-surface-variant shrink-0" aria-hidden="true" />
    </BaseMenu.SubmenuTrigger>
  )
);
MenuSubmenuTrigger.displayName = 'MenuSubmenuTrigger';

export const MenuGroupLabel = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.GroupLabel>
>(({ className, ...props }, ref) => (
  <BaseMenu.GroupLabel
    ref={ref}
    data-slot="menu-label"
    className={composeClassName('px-3 py-1.5 font-label text-xs font-semibold text-on-surface-variant select-none', className)}
    {...props}
  />
));
MenuGroupLabel.displayName = 'MenuGroupLabel';

export const MenuGroup = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.Group>
>(({ className, ...props }, ref) => (
  <BaseMenu.Group ref={ref} data-slot="menu-group" className={composeClassName('py-1', className)} {...props} />
));
MenuGroup.displayName = 'MenuGroup';

export const MenuRadioGroup = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.RadioGroup>
>(({ className, ...props }, ref) => (
  <BaseMenu.RadioGroup ref={ref} data-slot="menu-radio-group" className={composeClassName('py-1', className)} {...props} />
));
MenuRadioGroup.displayName = 'MenuRadioGroup';

export const MenuLinkItem = React.forwardRef<
  HTMLAnchorElement,
  React.ComponentPropsWithoutRef<typeof BaseMenu.LinkItem>
>(({ className, href, ...props }, ref) => (
  <BaseMenu.LinkItem
    ref={ref}
    data-slot="menu-link-item"
    href={href === undefined ? undefined : sanitizeUrl(href)}
    className={composeClassName(
      'flex items-center gap-2.5 px-3 py-2 min-h-[44px] rounded-sm font-sans text-sm font-medium cursor-pointer outline-none transition-colors motion-reduce:transition-none select-none text-on-surface hover:bg-state-hover focus:bg-state-hover data-[highlighted]:bg-state-hover data-[highlighted]:text-on-surface data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed data-[disabled]:pointer-events-none',
      className
    )}
    {...props}
  />
));
MenuLinkItem.displayName = 'MenuLinkItem';

export interface MenuProps<Payload = unknown> {
  label?: React.ReactNode;
  description?: React.ReactNode;
  triggerLabel?: string;
  trigger?: React.ReactNode;
  items?: MenuItemData[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean, eventDetails: BaseMenu.Root.ChangeEventDetails) => void;
  onOpenChangeComplete?: (open: boolean) => void;
  onItemHighlighted?: BaseMenu.Root.Props<Payload>['onItemHighlighted'];
  modal?: boolean;
  loopFocus?: boolean;
  highlightItemOnHover?: boolean;
  orientation?: 'horizontal' | 'vertical';
  disabled?: boolean;
  closeParentOnEsc?: boolean;
  openOnHover?: boolean;
  delay?: number;
  closeDelay?: number;
  actionsRef?: React.RefObject<BaseMenu.Root.Actions | null>;
  handle?: BaseMenu.Handle<Payload>;
  triggerId?: string | null;
  defaultTriggerId?: string | null;
  finalFocus?: BaseMenu.Popup.Props['finalFocus'];
  keepMounted?: boolean;
  showArrow?: boolean;
  container?: BaseMenu.Portal.Props['container'];
  side?: BaseMenu.Positioner.Props['side'];
  align?: BaseMenu.Positioner.Props['align'];
  sideOffset?: BaseMenu.Positioner.Props['sideOffset'];
  alignOffset?: BaseMenu.Positioner.Props['alignOffset'];
  collisionPadding?: BaseMenu.Positioner.Props['collisionPadding'];
  fullWidth?: boolean;
  triggerClassName?: BaseMenu.Trigger.Props['className'];
  popupClassName?: BaseMenu.Popup.Props['className'];
  className?: BaseMenu.Popup.Props['className'];
  children?: BaseMenu.Root.Props<Payload>['children'];
}

function MenuComponent<Payload = unknown>({
  label,
  description,
  triggerLabel = 'Menu',
  trigger,
  items,
  open,
  defaultOpen,
  onOpenChange,
  onOpenChangeComplete,
  onItemHighlighted,
  modal = true,
  loopFocus = true,
  highlightItemOnHover = true,
  orientation = 'vertical',
  disabled = false,
  closeParentOnEsc = false,
  openOnHover,
  delay,
  closeDelay,
  actionsRef,
  handle,
  triggerId,
  defaultTriggerId,
  finalFocus,
  keepMounted,
  showArrow = false,
  container,
  side,
  align,
  sideOffset = 4,
  alignOffset,
  collisionPadding = 8,
  fullWidth = true,
  triggerClassName,
  popupClassName,
  className,
  children,
}: MenuProps<Payload>): React.JSX.Element {
  const generatedId = React.useId();
  const menuId = `menu-${generatedId}`;

  // If used as composable compound root (<Menu open={...}><MenuTrigger /><MenuContent /></Menu>)
  if (!trigger && !items && !label && !description) {
    return (
      <BaseMenu.Root<Payload>
        open={open}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
        onOpenChangeComplete={onOpenChangeComplete}
        onItemHighlighted={onItemHighlighted}
        modal={modal}
        loopFocus={loopFocus}
        highlightItemOnHover={highlightItemOnHover}
        orientation={orientation}
        disabled={disabled}
        closeParentOnEsc={closeParentOnEsc}
        actionsRef={actionsRef}
        handle={handle}
        triggerId={triggerId}
        defaultTriggerId={defaultTriggerId}
      >
        {children}
      </BaseMenu.Root>
    );
  }

  const renderChildren = (renderProps: { payload: Payload | undefined }) => {
    if (typeof children === 'function') {
      return children(renderProps);
    }
    return children;
  };

  const combinedPopupClassName: BaseMenu.Popup.Props['className'] =
    typeof className === 'function' || typeof popupClassName === 'function'
      ? (state) =>
          cn(
            typeof className === 'function' ? className(state) : className,
            typeof popupClassName === 'function' ? popupClassName(state) : popupClassName
          )
      : cn(className, popupClassName) || undefined;

  const menuTree = (
    <BaseMenu.Root<Payload>
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={onOpenChangeComplete}
      onItemHighlighted={onItemHighlighted}
      modal={modal}
      loopFocus={loopFocus}
      highlightItemOnHover={highlightItemOnHover}
      orientation={orientation}
      disabled={disabled}
      closeParentOnEsc={closeParentOnEsc}
      actionsRef={actionsRef}
      handle={handle}
      triggerId={triggerId}
      defaultTriggerId={defaultTriggerId}
    >
      {(renderProps) => (
        <>
          {trigger ? (
            <BaseMenu.Trigger
              id={menuId}
              data-slot="menu-trigger"
              openOnHover={openOnHover}
              delay={delay}
              closeDelay={closeDelay}
              render={React.isValidElement(trigger) ? trigger : undefined}
              nativeButton={resolveNativeButton(trigger)}
            >
              {!React.isValidElement(trigger) ? trigger : undefined}
            </BaseMenu.Trigger>
          ) : (
            <BaseMenu.Trigger
              id={menuId}
              data-slot="menu-trigger"
              openOnHover={openOnHover}
              delay={delay}
              closeDelay={closeDelay}
              className={composeClassName(
                cn(
                  'inline-flex items-center justify-between gap-2 h-11 px-4 min-h-[44px] rounded border border-outline bg-surface text-on-surface font-label text-sm font-semibold hover:bg-state-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary transition-colors motion-reduce:transition-none cursor-pointer select-none disabled:opacity-50 disabled:cursor-not-allowed',
                  fullWidth ? 'w-full' : 'w-max'
                ),
                triggerClassName
              )}
            >
              <span>{triggerLabel}</span>
              <Icon name="arrow_drop_down" size="md" className="text-on-surface-variant" aria-hidden="true" />
            </BaseMenu.Trigger>
          )}
          <BaseMenu.Portal container={container} keepMounted={keepMounted}>
            <MenuPositioner
              side={side}
              align={align}
              sideOffset={sideOffset}
              alignOffset={alignOffset}
              collisionPadding={collisionPadding}
            >
              <MenuPopup finalFocus={finalFocus} className={combinedPopupClassName}>
                {showArrow && <MenuArrow />}
                <ScrollArea
                  className="min-h-0 flex-[0_1_auto]"
                  viewportClassName="overscroll-contain scroll-py-1"
                  viewportProps={{
                    tabIndex: -1,
                    onMouseDown: (e) => {
                      const target = e.target as HTMLElement | null;
                      if (target?.closest('input, textarea, [contenteditable]')) return;
                      e.preventDefault();
                    },
                  }}
                  contentClassName="p-1"
                >
                  {children ? (
                    renderChildren(renderProps)
                  ) : items ? (
                    <MenuGroup>
                      {items.map((item) => (
                        <MenuItem
                          key={item.id}
                          onClick={item.onClick}
                          disabled={item.disabled}
                          destructive={item.destructive}
                          icon={item.icon}
                        >
                          {item.label}
                        </MenuItem>
                      ))}
                    </MenuGroup>
                  ) : null}
                </ScrollArea>
              </MenuPopup>
            </MenuPositioner>
          </BaseMenu.Portal>
        </>
      )}
    </BaseMenu.Root>
  );

  if (label || description) {
    return (
      <div className="flex flex-col gap-1.5 w-full">
        {label && (
          <label htmlFor={menuId} className="font-label text-xs font-semibold text-on-surface-variant cursor-pointer select-none">
            {label}
          </label>
        )}
        {description && (
          <span className="font-sans text-sm text-on-surface-variant">
            {description}
          </span>
        )}
        {menuTree}
      </div>
    );
  }

  return menuTree;
}

export interface MenuInputProps extends React.ComponentPropsWithoutRef<typeof BaseMenu.Input> {
  showClear?: boolean;
  endAddon?: React.ReactNode;
}

export const MenuInput = React.forwardRef<HTMLInputElement, MenuInputProps>(
  ({ className, enterKeyHint = 'search', showClear = false, endAddon, ...props }, ref) => (
    <div className="flex items-center gap-2 px-3 py-2 border-b border-outline-variant shrink-0">
      <Icon name="search" size="md" className="text-on-surface-variant shrink-0 select-none" aria-hidden="true" />
      <BaseMenu.Input
        ref={ref}
        data-slot="menu-input"
        enterKeyHint={enterKeyHint}
        className={composeClassName(
          'w-full min-w-0 bg-transparent font-sans text-base sm:text-sm text-on-surface placeholder:text-on-surface-variant/80 outline-none disabled:cursor-not-allowed disabled:opacity-50',
